<script setup lang="ts">
import { ref,onMounted } from 'vue'
import AppLayout from '../layouts/AppLayout.vue';import DataTable from '../components/DataTable.vue';import FormDrawer from '../components/FormDrawer.vue';import ConfirmDialog from '../components/ConfirmDialog.vue';import PageState from '../components/PageState.vue';import { vehiclesApi } from '../api/vehicles';import { auditApi } from '../api/audit'
const rows=ref<any[]>([]),total=ref(0),page=ref(0),loading=ref(false),error=ref(''),drawer=ref(false),confirm=ref(false),audit=ref<any[]>([]),edit=ref<any>({}),form=ref<any>({make:'',model:'',modelYear:'',vin:'',source:'AUCTION',purchaseCost:'',addedOn:'',conditionCode:'AS_IS',repairCost:'',carfaxUrl:''}),filters=ref<any>({q:'',status:'',condition:''})
const load=async()=>{loading.value=true;error.value='';try{const r=await vehiclesApi.list({...filters.value,page:page.value,size:10});rows.value=r.data.items||[];total.value=r.data.total||0}catch{error.value='Could not load vehicles.'}finally{loading.value=false}}
function open(row?:any){edit.value=row;form.value=row?{...row}:{make:'',model:'',modelYear:'',vin:'',source:'AUCTION',purchaseCost:'',addedOn:'',conditionCode:'AS_IS',repairCost:'',carfaxUrl:''};drawer.value=true}
async function save(){if(edit.value){await vehiclesApi.update(edit.value.id,{...form.value,version:edit.value.version})}else await vehiclesApi.create(form.value);drawer.value=false;load()}
async function sell(){await vehiclesApi.sell(edit.value.id,{soldOn:form.value.soldOn,soldPrice:form.value.soldPrice,version:edit.value.version});confirm.value=false;drawer.value=false;load()}
async function loadAudit(){if(edit.value?.id){const r=await auditApi.list({entityType:'VEHICLE',entityId:edit.value.id});audit.value=r.data.items||[]}}
onMounted(load)
</script>
<template><AppLayout><div class="page"><div class="page-header"><div><h1>DMS</h1><span class="muted">Vehicle inventory</span></div><el-button type="primary" @click="open()">Add vehicle</el-button></div><div class="filters"><el-input v-model="filters.q" placeholder="VIN / Make / Model"/><el-select v-model="filters.status" placeholder="Status" clearable><el-option label="In stock" value="IN_STOCK"/><el-option label="Sold" value="SOLD"/></el-select><el-select v-model="filters.condition" placeholder="Condition" clearable><el-option v-for="v in ['CERTIFIED','AS_IS','UNFIT','IRREPARABLE']" :key="v" :label="v.replace('_',' ')" :value="v"/></el-select><el-button @click="page=0;load()">Search</el-button><el-button @click="filters={q:'',status:'',condition:''};page=0;load()">Reset</el-button></div><PageState :loading="loading" :error="error" :empty="!loading&&!error&&!rows.length" empty-text="No vehicles match." loading-text="Loading vehicles…"><DataTable :rows="rows" :total="total" :page="page" :row-class-name="({row}:any)=>row.status==='SOLD'?'sold-row':''" @page="p=>{page=p;load()}"><el-table-column label="Year Make Model"><template #default="{row}">{{row.modelYear}} {{row.make}} {{row.model}}</template></el-table-column><el-table-column prop="vin" label="VIN"/><el-table-column prop="source" label="Source"/><el-table-column prop="conditionCode" label="Condition"/><el-table-column prop="purchaseCost" label="Cost"/><el-table-column label="Status"><template #default="{row}"><el-tag>{{row.status}}</el-tag></template></el-table-column><template #actions="{row}"><el-button link @click="open(row)">Edit</el-button><el-button v-if="row.status!=='SOLD'" link @click="open({...row,sellMode:true})">Sell</el-button></template></DataTable></PageState></div><FormDrawer :title="edit?.sellMode?'Sell vehicle':edit?'Edit vehicle':'Add vehicle'" :visible="drawer" @close="drawer=false"><el-form label-position="top"><template v-if="!edit?.sellMode"><el-form-item v-for="key in ['make','model','modelYear','vin','purchaseCost','addedOn','repairCost','carfaxUrl']" :key="key" :label="key"><el-input v-model="form[key]" :disabled="edit?.status==='SOLD'"/></el-form-item><el-form-item label="Source"><el-select v-model="form.source"><el-option v-for="v in ['TRADE_IN','AUCTION','PRIVATE_PURCHASE','OTHER']" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="Condition"><el-select v-model="form.conditionCode"><el-option v-for="v in ['CERTIFIED','AS_IS','UNFIT','IRREPARABLE']" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-button type="primary" @click="save">Save</el-button></template><template v-else><el-form-item label="Sold date"><el-input v-model="form.soldOn" type="date"/></el-form-item><el-form-item label="Sold price"><el-input v-model="form.soldPrice"/></el-form-item><el-button type="primary" @click="sell">Confirm sale</el-button></template><el-divider/><el-button v-if="edit?.id&&!edit?.sellMode" @click="loadAudit">Load audit</el-button><el-table v-if="audit.length" :data="audit"><el-table-column prop="action" label="Action"/><el-table-column prop="createdAt" label="When"/></el-table></el-form></FormDrawer><ConfirmDialog :visible="false" @confirm="confirm=false" @cancel="confirm=false"/></AppLayout></template>
